-- The Nonprofit Guide is built, not launched (2026-10-29). Logged to its playbook and the stream. Safe to run twice.
insert into playbook_records (slug, brand_slug, author, kind, source, body)
select 've-nonprofit-guide','vegans-explore','Logan','decision','text',$v$Built 2026-10-29, not launched (Sean: "hand it to Logan"). /guides/nonprofit-guide (noindex): ten tabs with Dani's lines as text drafts; the 10 tips from the Canva doc (tip 1 free) with checklists and episodes; the Pulse (series 111 and 123 to 127, eleven nonprofit leaders) played in place; the Directory by chapter; Get found; Businesses with the pitch; Events and the peer-to-peer kit; Support; Become a Partner with the organization survey (100 points once, emailed to Sean). $11 or 1,100 points; a Nonprofit Partner's lead gets it with the partnership; Sean holds a copy to review. Two Canva claims corrected to their sources (Facebook birthday fundraisers: more than $1 billion by 2019; the Mercy For Animals and VegFund examples). Found and fixed: ve-cookbook had never been deployed with the Restaurant Guide, so that Guide's votes and saves had been failing live. Launch waits on Sean: the catalog card, noindex off, then Susan's invitation.$v$
where not exists (select 1 from playbook_records where slug='ve-nonprofit-guide' and author='Logan' and body like 'Built 2026-10-29%');
insert into stream_events (owner, station, summary, keywords, status, context_link)
select 'logan','vegans-explore','VEGANS EXPLORE: Nonprofit Guide built, not launched (/guides/nonprofit-guide, noindex; ve_guides nonprofit-guide; organization survey in ve-nonprofit; partner leads get the Guide). ve-cookbook redeployed: the Restaurant Guide''s votes and saves had been failing live since 2026-10-10.', array['vegans-explore','nonprofits','guides','build'], 'completed', 've-nonprofit-guide-built'
where not exists (select 1 from stream_events where context_link='ve-nonprofit-guide-built');
